function check([n, sums], actual) {
  if (!Array.isArray(actual) || actual.length !== n || !actual.every(Number.isInteger)) return false;
  let totals = [0];
  for (const x of actual) totals = totals.concat(totals.map(s => s + x));
  totals.sort((a, b) => a - b);
  const want = [...sums].sort((a, b) => a - b);
  return totals.every((s, i) => s === want[i]);
}

