function validate([n, sums]) {
  if (!Number.isInteger(n) || n < 1 || n > 15) return 'n is between 1 and 15.';
  if (!Array.isArray(sums) || sums.length !== 2 ** n) return 'sums must hold exactly 2^n values.';
  if (!sums.every(v => Number.isInteger(v) && v >= -10000 && v <= 10000)) return 'Each sum is between -10^4 and 10^4.';
  // Peel off one element at a time; if some sum finds no partner, no array produces these sums.
  let rest = [...sums].sort((a, b) => a - b);
  while (rest.length > 1) {
    const diff = rest[1] - rest[0];
    const count = new Map();
    for (const s of rest) count.set(s, (count.get(s) ?? 0) + 1);
    const low = [], high = [];
    for (const s of rest) {
      if (!count.get(s)) continue;
      count.set(s, count.get(s) - 1);
      if (!count.get(s + diff)) return 'No array has exactly these subset sums.';
      count.set(s + diff, count.get(s + diff) - 1);
      low.push(s);
      high.push(s + diff);
    }
    rest = low.includes(0) ? low : high;
  }
  return rest[0] === 0 ? null : 'No array has exactly these subset sums (the empty subset gives 0).';
}

