function recoverArray(n, sums) {
  sums.sort((a, b) => a - b);
  const answer = [];
  while (answer.length < n) {
    // The two smallest sums differ by the absolute value of some element.
    const diff = sums[1] - sums[0];
    const remaining = new Map();
    for (const sum of sums) {
      remaining.set(sum, (remaining.get(sum) ?? 0) + 1);
    }

    // Pair every unused sum with a partner exactly diff above it.
    const lower = [];
    const upper = [];
    for (const sum of sums) {
      if (remaining.get(sum) === 0) {
        continue;
      }
      remaining.set(sum, remaining.get(sum) - 1);
      remaining.set(sum + diff, remaining.get(sum + diff) - 1);
      lower.push(sum);
      upper.push(sum + diff);
    }

    // The half holding the empty subset's 0 is the sums of the other elements.
    if (lower.includes(0)) {
      answer.push(diff);
      sums = lower;
    } else {
      answer.push(-diff);
      sums = upper;
    }
  }
  return answer;
}

