function recoverArray(n, sums) {
  // Every element is itself a subset sum, so try multisets of values taken from sums.
  const need = new Map();
  for (const s of sums) need.set(s, (need.get(s) ?? 0) + 1);
  const candidates = [...need.keys()].sort((a, b) => a - b);
  const fits = list => {
    const count = new Map();
    for (const s of list) {
      count.set(s, (count.get(s) ?? 0) + 1);
      if (count.get(s) > (need.get(s) ?? 0)) return false;
    }
    return true;
  };
  // Grow the array one element at a time; all subset sums of a prefix must appear in sums.
  const search = (from, chosen, prefixSums) => {
    if (chosen.length === n) return chosen;
    for (let c = from; c < candidates.length; c++) {
      const grown = prefixSums.concat(prefixSums.map(s => s + candidates[c]));
      if (!fits(grown)) continue;
      const found = search(c, [...chosen, candidates[c]], grown);
      if (found) return found;
    }
    return null;
  };
  return search(0, [], [0]);
}

