function generate(rand, size) {
  const n = size === 'large' ? 10 : 1 + Math.floor(rand() * 4);
  let span;
  if (size === 'large') span = rand() < 0.5 ? 1000 : 3;
  else span = rand() < 0.7 ? 6 : 2500;
  const elements = Array.from({ length: n }, () => Math.floor(rand() * (2 * span + 1)) - span);
  let sums = [0];
  for (const x of elements) sums = sums.concat(sums.map(s => s + x));
  for (let i = sums.length - 1; i > 0; i--) {
    const j = Math.floor(rand() * (i + 1));
    [sums[i], sums[j]] = [sums[j], sums[i]];
  }
  return [n, sums];
}
